template.css:
@page { size: A4; margin: 15mm 16mm 16mm; }
* { box-sizing: border-box; } body { font-family: Inter; font-size: 10pt; line-height: 1.45; color: #203a32; background: #fbf8ef; }
.masthead { display:flex; justify-content:space-between; align-items:center; padding-bottom:16pt; border-bottom:1pt solid #d8ddd1; }
.brand { font-size:15pt; font-weight:700; max-width:65%; } .tag { font-size:8pt; color:#667064; text-align:right; }
.hero { margin:23pt 0 24pt; padding-left:15pt; border-left:5pt solid #c5542d; } .eyebrow { font-size:8pt; font-weight:700; letter-spacing:1.2pt; color:#667064; margin-bottom:6pt; }
h1 { font-family:'DM Serif Display'; font-size:43pt; line-height:1.06; font-weight:400; margin:0 0 9pt; } .order-number { font-size:13pt; font-weight:700; } .status { font-size:9pt; font-weight:400; color:#667064; margin-left:10pt; }
.addresses { display:flex; margin-bottom:23pt; gap:28pt; } .address { width:50%; overflow-wrap:anywhere; } .address strong { display:block; margin-bottom:3pt; }
table { width:100%; border-collapse:collapse; table-layout:fixed; } .description { width:64%; } .quantity { width:10%; text-align:center; } .amount { width:26%; text-align:right; }
th { padding:10pt 9pt; color:#fff; background:#203a32; font-size:8pt; font-weight:700; text-align:left; } td { padding:11pt 9pt; border-bottom:0.7pt solid #d8ddd1; vertical-align:top; overflow-wrap:anywhere; } tr { break-inside:avoid; }
.item-name { font-weight:600; } .sku { font-size:8pt; color:#667064; margin-top:3pt; } .check-box { display:inline-block; width:12pt; height:12pt; border:1pt solid #667064; }
.totals { margin:18pt 0 0 46%; break-inside:avoid; } .total-row { display:flex; justify-content:space-between; gap:10pt; padding:5pt 0; font-size:9pt; } .total-row strong { text-align:right; } .grand-total { border-top:1.5pt solid #203a32; margin-top:6pt; padding-top:10pt; font-size:14pt; }
.packing-note { margin-top:16pt; padding:12pt; background:#e9ede4; break-inside:avoid; } .packing-note p { margin:3pt 0 6pt; } .packing-closing { margin-top:7pt; padding-top:7pt; border-top:0.7pt solid #d8ddd1; font-size:9pt; }
.footer { margin-top:28pt; break-inside:avoid; } .footer-rule { width:34pt; height:4pt; background:#c5542d; margin-bottom:12pt; } .footer p { margin:0 0 5pt; font-size:10pt; } .footer-reference { font-size:8pt; color:#667064; }

.address-lines { white-space: pre-line; }
